        }
        #reset {
            background: #e74c3c;
            border: none;
            color: #fff;
            font-size: 14px;
            font-weight: 600;
            padding: 10px 26px;
            border-radius: 10px;
            cursor: pointer;
            letter-spacing: 0.5px;
            box-shadow: 0 4px 12px rgba(231, 76, 60, 0.35);
            transition: background 0.2s, transform 0.1s;
