</head>
<body>
    <div id="app">
        <div id="header">
            <div id="score-wrap">
                <div id="score-label">Score</div>
                <div id="score">0</div>
            </div>
            <button id="reset">New Game</button>
        </div>
        <div id="board"></div>
    </div>
    <script>
        (function() {
            const SIZE = 4;
            let grid = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
            let currentScore = 0;
            const boardEl = document.getElementById('board');
            const scoreEl = document.getElementById('score');

            // ----- helpers -----
            function cloneGrid(g) {
                return g.map(row => [...row]);
            }

            function gridsEqual(a, b) {
                for (let r = 0; r < SIZE; r++) {
                    for (let c = 0; c < SIZE; c++) {
                        if (a[r][c] !== b[r][c]) return false;
                    }
                }
                return true;
            }

            function getEmptyCells(g) {
                const cells = [];
                for (let r = 0; r < SIZE; r++) {
                    for (let c = 0; c < SIZE; c++) {
                        if (g[r][c] === 0) cells.push([r, c]);
                    }
                }
                return cells;
            }

            function addRandomTile(g) {
                const empty = getEmptyCells(g);
                if (empty.length === 0) return;
                const [r, c] = empty[Math.floor(Math.random() * empty.length)];
                g[r][c] = Math.random() < 0.9 ? 2 : 4;
            }

            // ----- slide logic -----
            function slideRow(row) {
                const tiles = row.filter(v => v !== 0);
                const result = [];
                let added = 0;
                let i = 0;
                while (i < tiles.length) {
                    if (i + 1 < tiles.length && tiles[i] === tiles[i + 1]) {
                        const merged = tiles[i] * 2;
                        result.push(merged);
                        added += merged;
                        i += 2;
                    } else {
                        result.push(tiles[i]);
                        i += 1;
                    }
                }
                while (result.length < SIZE) result.push(0);
                return { row: result, score: added };
            }

            // ----- directions -----
            function moveLeft(g) {
                let moved = false;
                let totalScore = 0;
                for (let r = 0; r < SIZE; r++) {
                    const old = [...g[r]];
                    const { row, score: add } = slideRow(g[r]);
                    g[r] = row;
                    if (!moved && row.join(',') !== old.join(',')) moved = true;
                    totalScore += add;
                }
                return { moved, score: totalScore };
            }

            function moveRight(g) {
                let moved = false;
                let totalScore = 0;
                for (let r = 0; r < SIZE; r++) {
                    const old = [...g[r]];
                    const reversed = [...g[r]].reverse();
                    const { row, score: add } = slideRow(reversed);
                    const newRow = row.reverse();
                    g[r] = newRow;
                    if (!moved && newRow.join(',') !== old.join(',')) moved = true;
                    totalScore += add;
                }
                return { moved, score: totalScore };
            }

            function moveUp(g) {
                let moved = false;
                let totalScore = 0;
                for (let c = 0; c < SIZE; c++) {
                    const col = [];
                    for (let r = 0; r < SIZE; r++) col.push(g[r][c]);
                    const old = [...col];
                    const { row, score: add } = slideRow(col);
                    for (let r = 0; r < SIZE; r++) g[r][c] = row[r];
                    if (!moved && row.join(',') !== old.join(',')) moved = true;
                    totalScore += add;
                }
                return { moved, score: totalScore };
            }

            function moveDown(g) {
                let moved = false;
                let totalScore = 0;
                for (let c = 0; c < SIZE; c++) {
                    const col = [];
                    for (let r = 0; r < SIZE; r++) col.push(g[r][c]);
                    const old = [...col];
                    const reversed = col.reverse();
                    const { row, score: add } = slideRow(reversed);
                    const newCol = row.reverse();
                    for (let r = 0; r < SIZE; r++) g[r][c] = newCol[r];
                    if (!moved && newCol.join(',') !== old.join(',')) moved = true;
                    totalScore += add;
                }
                return { moved, score: totalScore };
            }

            // ----- render -----
            function render() {
                boardEl.innerHTML = '';
                for (let r = 0; r < SIZE; r++) {
                    for (let c = 0; c < SIZE; c++) {
                        const val = grid[r][c];
                        const cell = document.createElement('div');
                        cell.className = 'cell';
                        const cls = val === 0 ? 'tile-0' :
                            val <= 8192 ? 'tile-' + val : 'tile-super';
                        cell.classList.add(cls);
                        if (val !== 0) cell.textContent = val;
                        boardEl.appendChild(cell);
                    }
                }
                scoreEl.textContent = currentScore;
            }

            // ----- public API -----
            function reset() {
                grid = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
                currentScore = 0;
                addRandomTile(grid);
                addRandomTile(grid);
                render();
            }

            function move(direction) {
                const old = cloneGrid(grid);
                let result;
                switch (direction) {
                    case 'left':
                        result = moveLeft(grid);
                        break;
                    case 'right':
                        result = moveRight(grid);
                        break;
                    case 'up':
                        result = moveUp(grid);
                        break;
                    case 'down':
                        result = moveDown(grid);
                        break;
                    default:
                        return false;
                }
                if (!result.moved) return false;
                currentScore += result.score;
                addRandomTile(grid);
                render();
                return true;
            }

            function board() {
                return cloneGrid(grid);
            }

            function setBoard(arr) {
                grid = arr.map(row => [...row]);
                render();
            }

            function score() {
                return currentScore;
            }

            // expose
            window.game = {
                size: SIZE,
                reset: reset,
                move: move,
                board: board,
                setBoard: setBoard,
                score: score,
            };

            // ----- keyboard -----
            document.addEventListener('keydown', function(e) {
                const key = e.key;
                let dir = null;
                if (key === 'ArrowLeft') dir = 'left';
                else if (key === 'ArrowRight') dir = 'right';
                else if (key === 'ArrowUp') dir = 'up';
                else if (key === 'ArrowDown') dir = 'down';
                if (dir) {
                    e.preventDefault();
                    move(dir);
                }
            });

            // ----- reset button -----
            document.getElementById('reset').addEventListener('click', reset);

            // ----- init -----
            reset();
        })();
    </script>
</body>
</html>
